using System.Collections.Generic;
using Godot;
using SandlotSlugfest.Core;

namespace SandlotSlugfest.Data;

/// <summary>
/// A deliberate appearance, for the handcrafted kids. Any field left at its sentinel is still
/// rolled from the player's look seed, so a written character only has to specify what makes him
/// recognisable.
/// </summary>
public readonly struct LookSpec
{
    public readonly int Skin, Hair, HairStyle, Cap, Ears;      // -1 = from the seed
    public readonly float Chub, Height, HeadSize, HeadWidth;   //  0 = from the seed
    public readonly sbyte Glasses, Freckles, Headband;         // -1 unset, 0 no, 1 yes

    public LookSpec(int skin = -1, int hair = -1, int hairStyle = -1, int cap = -1,
        float chub = 0f, float height = 0f, float headSize = 0f, float headWidth = 0f,
        sbyte glasses = -1, sbyte freckles = -1, sbyte headband = -1, int ears = -1)
    {
        Skin = skin; Hair = hair; HairStyle = hairStyle; Cap = cap; Ears = ears;
        Chub = chub; Height = height; HeadSize = headSize; HeadWidth = headWidth;
        Glasses = glasses; Freckles = freckles; Headband = headband;
    }
}

/// <summary>One of the written kids: a fixed name, look, game and reputation.</summary>
public sealed class Legend
{
    public string First, Last, Bio;
    public Position Position;
    public Handedness Bats = Handedness.Right, Throws = Handedness.Right;
    public Archetype Archetype = Archetype.Balanced;
    public Special Special = Special.None;
    public int Number, Age = 27, Potential = 8;
    public int Contact, Power, Speed, Arm, Fielding, PitchPower, PitchControl, Stamina;
    public LookSpec Look;
}

/// <summary>
/// The named kids.
///
/// Procedural generation gives a league breadth, but nobody remembers a distribution — people
/// remember a particular kid who was unfairly good. These forty are written by hand: fixed
