    public static int Count => All.Length;

    /// <summary>
    /// How many written players make up the opening league. Everything past this is a reserve of
    /// young prospects, drawn on by draft classes and by clubs replacing a retirement — so the
    /// league keeps being made of written people for years rather than filling with generated
    /// filler at about a tenth a season.
    /// </summary>
    public const int OpeningLeague = 512;

    /// <summary>Reserve entries not placed at the start, in a stable order.</summary>
    public static int ReserveCount => Mathf.Max(0, All.Length - OpeningLeague);

    /// <summary>
    /// Takes the next unused reserve player. Returns null once the reserve runs dry, at which
    /// point the caller falls back to the generator.
    /// </summary>
    /// <param name="wantPitcher">
    /// Filters the reserve to arms or to bats. Callers used to draw blind and throw back anyone of
    /// the wrong kind, but a draw marks a written player used whether or not he is kept — so a
    /// club looking for pitching quietly deleted every position player it turned down.
    /// </param>
    public static PlayerData DrawFromReserve(HashSet<int> alreadyUsed, int playerId,
        bool? wantPitcher = null)
    {
        for (int i = OpeningLeague; i < All.Length; i++)
        {
            if (alreadyUsed.Contains(i)) continue;
            if (wantPitcher is { } arm && (All[i].Position == Position.P) != arm) continue;
            alreadyUsed.Add(i);
            return Make(i, playerId);
        }
        return null;
    }

    public static Legend Get(int id) => All[Mathf.Clamp(id, 0, All.Length - 1)];

    public static LookSpec Spec(int id) => Get(id).Look;

    public static string Bio(int id) => Get(id).Bio;

    /// <summary>
    /// Which written players start on a club. Spread evenly so every team carries three of them,
    /// and fixed by team id so the same faces are always in the same places.
    /// </summary>
    public static System.Collections.Generic.List<int> ForTeam(int teamId)
    {
        var ids = new System.Collections.Generic.List<int>();
        // Only the opening league is placed; the rest is reserve for later years.
        for (int i = teamId % 32; i < Mathf.Min(All.Length, OpeningLeague); i += 32) ids.Add(i);
        return ids;
    }

    /// <summary>Builds the player record for a named kid.</summary>
    public static PlayerData Make(int id, int playerId)
    {
        var l = Get(id);
        var p = new PlayerData
        {
            Id = playerId,
            LegendId = id,
            FirstName = l.First,
            LastName = l.Last,
            Number = l.Number,
            Position = l.Position,
            Bats = l.Bats,
            Throws = l.Throws,
            Archetype = l.Archetype,
            Special = l.Special,
            Contact = l.Contact,
            Power = l.Power,
            Speed = l.Speed,
            Arm = l.Arm,
            Fielding = l.Fielding,
            PitchPower = l.PitchPower,
            PitchControl = l.PitchControl,
            Stamina = l.Stamina,
            Age = l.Age,
            Potential = l.Potential,
            LookSeed = 90000 + id * 131,
        };

        // Everyone throws a fastball; a signature move always brings its own pitch.
        p.Repertoire = 1 << (int)PitchType.Fastball;
        if (l.PitchControl >= 6) p.Repertoire |= 1 << (int)PitchType.Changeup;
        if (l.PitchControl >= 8) p.Repertoire |= 1 << (int)PitchType.Slider;
        p.Repertoire |= l.Special switch
        {
            Special.CrazyCurve => 1 << (int)PitchType.Curveball,
            Special.Corkscrew => 1 << (int)PitchType.Slider,
            Special.Knuckleball => 1 << (int)PitchType.Changeup,
            _ => 0,
        };
        return p;
    }
}
